describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      2000,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 for zero-weight items", () => {
      const lines: CartLine[] = [
        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 3 },
      ];
      expect(calc.computeShippingCents(lines, 300)).toBe(0);
    });

    it("selects the first bracket whose upToGrams >= weight", () => {
      // 400g total → first bracket (≤500g) → 300
      expect(calc.computeShippingCents([makeLine("a", 200, 2)], 1000)).toBe(300);
    });

    it("selects exact boundary match", () => {
      // 500g exactly → first bracket boundary
      expect(calc.computeShippingCents([makeLine("a", 500, 1)], 1000)).toBe(300);
    });

    it("selects next bracket when weight exceeds first", () => {
      // 501g → second bracket (≤2000g) → 700
      expect(calc.computeShippingCents([makeLine("a", 501, 1)], 1000)).toBe(700);
    });

    it("selects the heaviest bracket at its boundary", () => {
      // 5000g → third bracket → 1200
      expect(calc.computeShippingCents([makeLine("a", 2500, 2)], 1000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      // 5001g → overflow → 2000
      expect(calc.computeShippingCents([makeLine("a", 5001, 1)], 1000)).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflow set", () => {
      const calcNoOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 3000, costCents: 900 },
      ]);
      // 5000g exceeds all → last bracket's cost = 900
      expect(calcNoOverflow.computeShippingCents([makeLine("a", 5000, 1)], 1000)).toBe(900);
    });

    it("sorts brackets regardless of input order", () => {
      const calcUnordered = new WeightBasedShippingCalculator([
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ]);
      // 400g → first (sorted) bracket = 300
      expect(calcUnordered.computeShippingCents([makeLine("a", 400, 1)], 1000)).toBe(300);
    });
  });
});

